        final String selectedGermanyKey=germanyKey;best.at nativeGermany=projection.remoteCompetition(selectedGermanyKey);check(((f.s)nativeGermany.mB()[0]).yK().size()==Data.list(gt.get("rows")).size(),"Native standings lost clubs");check(Data.list(gt.get("rounds")).size()>0,"Native round catalog is empty");SwingUtilities.invokeLater(()->NativeCareerScreens.openTables(new JFrame("Tabelas nativas"),projection.remoteCompetition(selectedGermanyKey)));JDialog standings=dialog("Tabelas - ");check(standings!=null,"Original Brasfoot tables window did not open");check(standings.getContentPane().getComponentCount()>0,"Original tables window has no native content");new Robot().waitForIdle();Thread.sleep(250);ImageIO.write(new Robot().createScreenCapture(standings.getBounds()),"png",evidence.resolve("tables.png").toFile());JLabel rounds=findLabel(standings.getContentPane(),"Rodadas");check(rounds!=null,"Original tables view does not expose the native Rodadas control");SwingUtilities.invokeAndWait(()->{for(java.awt.event.MouseListener listener:rounds.getMouseListeners())listener.mouseClicked(new java.awt.event.MouseEvent(rounds,java.awt.event.MouseEvent.MOUSE_CLICKED,System.currentTimeMillis(),0,5,5,1,false));});new Robot().waitForIdle();Thread.sleep(250);List<JTable> roundTables=new ArrayList<JTable>();collect(standings.getContentPane(),roundTables);boolean populatedRounds=false;for(JTable grid:roundTables)if(grid.getRowCount()>0)populatedRounds=true;check(populatedRounds,"Original Rodadas view has no fixtures");ImageIO.write(new Robot().createScreenCapture(standings.getBounds()),"png",evidence.resolve("rounds.png").toFile());SwingUtilities.invokeAndWait(standings::dispose);for(Window window:Window.getWindows())SwingUtilities.invokeAndWait(window::dispose);System.out.println("PASS calendar dates="+fixtureDates.size()+", club dates="+clubFixtureLabels.size()+", clubFixtures="+expectedClubFixtures+", six countries, native standings and rounds: "+clubFixtureLabels);System.exit(0);
        System.out.println("PASS host returns six-country fixtures and standings; original Agenda and Tabelas/Rodadas render populated native data");
