    private static void collect(Container root,List<JTable> out){for(Component child:root.getComponents()){if(child instanceof JTable)out.add((JTable)child);if(child instanceof Container)collect((Container)child,out);}}
    private static JLabel findLabel(Container root,String text){for(Component child:root.getComponents()){if(child instanceof JLabel&&text.equals(((JLabel)child).getText()))return (JLabel)child;if(child instanceof Container){JLabel found=findLabel((Container)child,text);if(found!=null)return found;}}return null;}
